Here is a C++ function that converts markdown formatted text to HTML formatted text:

```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex regex(R"(#\\s*.*)");
    std::smatch match;
    while (std::regex_search(html, match, regex)) {
        html = html.replace(html.find(match[0].str(), match[0].length()), match[0].length(), "<h>" + match[1].str() + "</h>");
    }
    return html;
}

int main() {
    std::string markdown = "# Section 1\n## Section 2\n### Section 3";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a regular expression to match markdown headings and replace them with HTML `<h>` tags. The regular expression pattern `#\s*.*` matches lines that start with a `#` and contain any characters after it. The `std::regex_search` function is used to find all matches in the markdown string, and the `replace` function is used to replace each match with the HTML tags.

